    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  assertNotArchived("Organization", input.orgId, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const deleted = await orgRepo.archiveOrg(input.orgId);

  await emit("organization.deleted", {
    ...actorEnvelope(actor),
    slug: deleted.slug,
  });

  return deleted;
}

/**
 * Brings a deleted workspace back during its retention window. A deleted
 * workspace resolves to no `Actor`, so the caller is identified by user id and
 * the membership read is what makes them one. No workspace, no membership and
 * a closed window all read as "not found", so an outsider learns nothing.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const member = requireFound(
    await memberRepo.findMember(orgId, userId),
    "Organization",
    orgId,
  );

  const actor: Actor = { userId, orgId, role: member.role };
  assertCan(actor, "org:restore", orgResource(orgId));

  if (org.archivedAt === null) return org;

  const windowClosesAt =
    Date.parse(org.archivedAt) + DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
  if (Date.now() >= windowClosesAt) {
    throw new NotFoundError("Organization", orgId);
  }

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...actorEnvelope(actor),
    slug: restored.slug,
  });

  return restored;
}

