import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { NotFoundError } from "@/server/services/_support";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as organizationService from "@/server/services/organization-service";
import * as memberService from "@/server/services/member-service";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
const DAY = 24 * 60 * 60 * 1000;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("scratch");
});
afterAll(() => {
  vi.useRealTimers();
  cleanup();
});

describe("scratch", () => {
  it("delete, restore, purge", async () => {
    vi.setSystemTime(new Date("2026-06-01T00:00:00.000Z"));
    const id = tenant.org.id;
    const userId = tenant.userIds.owner;

    await organizationService.deleteOrganization(tenant.actors.owner, { orgId: id, confirmSlug: "scratch" } as never);
    await expect(
      organizationService.deleteOrganization(tenant.actors.owner, { orgId: id, confirmSlug: "scratch" } as never),
    ).rejects.toThrow();
    expect(await memberService.resolveActor(userId, id)).toBeNull();

    // Restore inside the window.
    vi.setSystemTime(new Date("2026-06-10T00:00:00.000Z"));
    await expect(organizationService.restoreOrganization(tenant.userIds.member, id)).rejects.toBeInstanceOf(Error);
    const restored = await organizationService.restoreOrganization(userId, id);
    expect(restored.archivedAt).toBeNull();
    expect(await memberService.resolveActor(userId, id)).not.toBeNull();
    // Restoring a live workspace returns it unchanged.
    expect((await organizationService.restoreOrganization(userId, id)).id).toBe(id);

    // Delete again, let the window close, purge.
    vi.setSystemTime(new Date("2026-07-01T00:00:00.000Z"));
    await organizationService.deleteOrganization(tenant.actors.owner, { orgId: id, confirmSlug: "scratch" } as never);
    vi.setSystemTime(new Date("2026-07-01T00:00:00.000Z").getTime() + 29 * DAY);
    await runCleanupArchivedJob(new Date(Date.now()));
    expect(await orgRepo.findOrgById(id)).not.toBeNull();

    vi.setSystemTime(new Date("2026-07-01T00:00:00.000Z").getTime() + 31 * DAY);
    const result = await runCleanupArchivedJob(new Date(Date.now()));
    expect(result.failed).toBe(0);
    expect(await orgRepo.findOrgById(id)).toBeNull();
    await expect(organizationService.restoreOrganization(userId, id)).rejects.toBeInstanceOf(NotFoundError);
    expect(await orgRepo.listTakenOrgSlugs("scratch")).toEqual([]);
    expect(await invitationRepo.listPendingInvitations(id)).toEqual([]);
  });
});
